class OKOVLMChapters23Trigger:
    def __init__(self, event_bus: Any = None):
        self.event_bus = event_bus

    def register(self, event_name: str = 'oko_vlm_chapters_23.start'):
        if self.event_bus:
            self.event_bus.subscribe(event_name, self._handler)

    def _handler(self, event_data: dict = None):
        config_data = event_data or {}
        config = OKOVLMChapters23Config(
            chapter_2_param=config_data.get('ch2', 'default_ch2'),
            chapter_3_param=config_data.get('ch3', 'default_ch3')
        )
        task = OKOVLMChapters23Factory.create(config)
        return task.execute()

    def trigger_manual(self, **kwargs):
        return self._handler(kwargs)
